import { Link } from "react-router-dom";
import { getAccessoryById } from "../data/accessories";
import useAuth from "../hooks/useAuth";
import { addToWishlist } from "../firebase/database";

export default function ProductCard({ product }) {
  const { user } = useAuth();
  const tryOnAccessoryId = product.accessoryId ?? product.id;
  const tryOnAccessory = getAccessoryById(tryOnAccessoryId);
  const thumbnailUrl = product.previewUrl ?? tryOnAccessory?.thumbnailUrl ?? product.thumbnailUrl;

  async function handleSave() {
    if (user?.uid) {
      try {
        await addToWishlist(user.uid, product.id);
      } catch (e) {
        console.error("Failed to save to wishlist:", e);
      }
    }
  }

  return (
    <article className="rounded-3xl border border-rose-100 bg-white p-5 shadow-aura">
      <div className="mb-4 overflow-hidden rounded-2xl bg-aura-secondary/14">
        <img
          src={thumbnailUrl}
          alt={product.name}
          className="h-48 w-full object-contain p-4"
          onError={(e) => {
            e.target.onerror = null;
            e.target.src = "/assets/products/earrings.png";
          }}
        />
      </div>
      <div className="mb-3 flex items-center justify-between gap-3">
        <p className="text-sm uppercase tracking-[0.2em] text-aura-accent">{product.category}</p>
        <span
          className={[
            "rounded-full px-3 py-1 text-xs font-semibold",
            product.arSupported && tryOnAccessory?.modelUrl
              ? "bg-emerald-50 text-emerald-700"
              : "bg-stone-100 text-stone-500"
          ].join(" ")}
        >
          {product.arSupported && tryOnAccessory?.modelUrl ? "3D Try-On" : "Planned"}
        </span>
      </div>
      <h3 className="font-display text-xl text-aura-charcoal">{product.name}</h3>
      <p className="mt-2 text-stone-600">NPR {product.price}</p>
      <div className="mt-4 flex gap-3">
        <Link
          to={`/product/${product.id}`}
          className="rounded-full bg-aura-primary px-4 py-2 text-sm font-semibold text-white"
        >
          View Details
        </Link>
        <button
          onClick={handleSave}
          className="rounded-full border border-aura-secondary/50 px-4 py-2 text-sm font-semibold text-aura-primary hover:bg-aura-secondary/10"
        >
          Save
        </button>
      </div>
    </article>
  );
}